<?php declare(strict_types=1); require __DIR__.'/_bootstrap.php';require_admin();$pageTitle='Hero Slides';$active='slides';$slides=$pdo->query('SELECT * FROM hero_slides ORDER BY sort_order,id')->fetchAll();require __DIR__.'/includes/layout.php';?><div class="panel"><div class="panel-head"><div><h2>Homepage hero slider</h2><p style="color:#687589;font-size:12px">Slides are served from the database. The public site uses random transition animations.</p></div><a class="btn btn-gold" href="slide.php">+ Add slide</a></div><div class="table-wrap"><table><thead><tr><th>Image</th><th>Content</th><th>CTA</th><th>Order</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($slides as $s): ?><tr><td><img class="thumb" src="../<?=e($s['image_path'])?>" alt=""></td><td><b><?=e($s['title'])?></b><br><small><?=e($s['eyebrow'])?></small></td><td><?=e($s['cta_text'])?></td><td><?= (int)$s['sort_order'] ?></td><td><?= $s['is_active']?'Active':'Hidden' ?></td><td class="actions"><a class="btn btn-light" href="slide.php?id=<?= (int)$s['id'] ?>">Edit</a><form method="post" action="slide_delete.php"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?= (int)$s['id'] ?>"><button class="btn btn-danger" data-confirm="Delete this hero slide?">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></div><?php require __DIR__.'/includes/footer.php';?>
